//! The agent: model + tools + message history + the tool-calling loop.

use std::sync::Arc;

use futures::StreamExt as _;
use rig::client::CompletionClient;
use rig::completion::message::ToolCall;
use rig::completion::{
    AssistantContent, CompletionModel, GetTokenUsage, Message, ToolDefinition, Usage,
};
use rig::providers::openai;
use rig::tool::PortableDynamicTool;
use tokio::sync::mpsc;

use crate::error::AgentError;

/// Default system prompt used when none is supplied.
pub const DEFAULT_SYSTEM_PROMPT: &str = "You are a helpful assistant running in an agent harness. \
You have access to tools. Use them when they help answer the user; otherwise answer directly. \
When a tool result comes back, incorporate it into your final answer.";

/// System prompt for task mode: long-horizon self-improvement work with
/// explicit workflow gates (mirrors the project's Rust workflow rules).
pub const TASK_SYSTEM_PROMPT: &str = "You are hānihi in task mode: a coding agent working on a Rust codebase. \
Work in small steps and verify with the build before declaring success. Workflow gates: \
run `cargo fmt` before staging changes; `cargo test` before committing; `cargo build` must pass; \
run `cargo clippy -- -D warnings` before finishing. Make changes as small git commits with \
descriptive messages. Never push. Study command output and trace files before retrying: if a \
command fails, read the error and fix the cause rather than repeating it. Verify your work with \
the build/test gates — do not assert success by eye.";

/// Result of one `Agent::run` invocation.
#[derive(Debug, Clone)]
pub struct TurnSummary {
    /// Final assistant text.
    pub text: String,
    /// Number of tool calls executed during the turn.
    pub tool_calls: usize,
    /// Total token usage across all model calls in the turn.
    pub usage: Usage,
    /// Final message history after the turn (for streaming — the agent's
    /// history is updated in the spawned task; the caller seeds it back).
    pub final_history: Vec<Message>,
}

/// Events emitted during a streaming agent turn.
#[derive(Debug, Clone)]
pub enum StreamEvent {
    /// Delta of assistant text.
    TextDelta { text: String },
    /// Model has started a tool call (name known, arguments assembling).
    ToolCallStart { id: String, name: String },
    /// Fragment of tool call arguments (partial JSON).
    ToolCallArgs { id: String, args_delta: String },
    /// Tool call is complete and about to be executed.
    ToolCallReady {
        id: String,
        name: String,
        arguments: serde_json::Value,
    },
    /// Tool has executed successfully.
    ToolResult {
        id: String,
        name: String,
        /// Truncated preview of the result (for inline display).
        result_preview: String,
        /// Full rendered result (for session-log persistence).
        result: String,
    },
    /// Turn completed successfully.
    TurnComplete { summary: TurnSummary },
    /// An error occurred during the turn.
    Error { message: String },
}

/// Connect to an OpenAI-compatible chat completions endpoint (e.g. DeepSeek)
/// and return an agent bound to it.
///
/// The concrete model type is hidden behind `impl CompletionModel` so callers
/// never need to name it.
pub fn connect_chat_model(
    base_url: String,
    api_key: String,
    model: String,
) -> Result<Agent<impl CompletionModel + use<>>, AgentError> {
    connect_chat_model_with_prompt(base_url, api_key, model, DEFAULT_SYSTEM_PROMPT)
}

/// Like [`connect_chat_model`], but with a custom system prompt (e.g. the
/// task-mode prompt for self-improvement work).
pub fn connect_chat_model_with_prompt(
    base_url: String,
    api_key: String,
    model: String,
    system_prompt: &str,
) -> Result<Agent<impl CompletionModel + use<>>, AgentError> {
    let client = openai::CompletionsClient::builder()
        .api_key(&api_key)
        .base_url(&base_url)
        .build()
        .map_err(|e| AgentError::Rig(e.to_string()))?;
    let model = client.completion_model(&model);
    Ok(Agent::new(model, system_prompt))
}

/// A minimal tool-calling agent.
///
/// Generic over the rig [`CompletionModel`]; unit tests use rig's
/// `MockCompletionModel`, production uses the OpenAI-compatible client from
/// [`connect_chat_model`].
pub struct Agent<M: CompletionModel> {
    model: M,
    system_prompt: String,
    tools: Arc<Vec<PortableDynamicTool>>,
    history: Vec<Message>,
    max_turns: usize,
}

impl<M: CompletionModel> Agent<M> {
    /// Create an agent with no tools and an empty history.
    pub fn new(model: M, system_prompt: impl Into<String>) -> Self {
        Self {
            model,
            system_prompt: system_prompt.into(),
            tools: Arc::new(Vec::new()),
            history: Vec::new(),
            max_turns: 10,
        }
    }

    /// The system prompt.
    pub fn system_prompt(&self) -> &str {
        &self.system_prompt
    }

    /// Register a tool. The agent exposes it to the model on the next turn.
    pub fn add_tool(&mut self, tool: PortableDynamicTool) {
        Arc::make_mut(&mut self.tools).push(tool);
    }

    /// Clone of the shared tool registry (for use in spawned tasks).
    fn tools_arc(&self) -> Arc<Vec<PortableDynamicTool>> {
        self.tools.clone()
    }

    /// Tool inventory (name, description, JSON schema).
    pub fn tool_definitions(&self) -> Vec<ToolDefinition> {
        self.tools.iter().map(|t| t.definition()).collect()
    }

    /// Number of registered tools.
    pub fn tool_count(&self) -> usize {
        self.tools.len()
    }

    /// Persistent message history (prior turns only).
    pub fn history(&self) -> &[Message] {
        &self.history
    }

    /// Maximum model turns per `run` invocation.
    pub fn max_turns(&self) -> usize {
        self.max_turns
    }

    /// Set the maximum model turns per `run` invocation.
    pub fn set_max_turns(&mut self, max_turns: usize) {
        self.max_turns = max_turns;
    }

    /// Clear the persistent message history.
    pub fn clear_history(&mut self) {
        self.history.clear();
    }

    /// Replace the persistent message history (e.g. from session replay).
    pub fn set_history(&mut self, history: Vec<Message>) {
        self.history = history;
    }

    /// Run a single completion call against the model.
    ///
    /// Assembles the request from `user_input` + persistent history +
    /// in-progress turn messages + tool definitions, sends it to the
    /// model, and returns the response. `Session` uses this to interpose
    /// logging between calls.
    pub(crate) async fn single_completion(
        &self,
        user_input: &str,
        turn_messages: &[Message],
    ) -> Result<rig::completion::CompletionResponse<M::Response>, AgentError> {
        let request = self
            .model
            .completion_request(Message::user(user_input))
            .preamble(self.system_prompt.clone())
            .messages(self.history.iter().chain(turn_messages.iter()).cloned())
            .tools(self.tool_definitions())
            .build();
        let response = self.model.completion(request).await?;
        Ok(response)
    }

    /// Run one user request to completion: model calls, tool execution, and
    /// follow-up model calls until the model answers without tool calls.
    pub async fn run(&mut self, user_input: &str) -> Result<TurnSummary, AgentError> {
        let mut turn_messages: Vec<Message> = Vec::new();
        let mut tool_calls_total = 0usize;
        let mut usage_total = Usage::new();

        for _ in 0..self.max_turns {
            let request = self
                .model
                .completion_request(Message::user(user_input))
                .preamble(self.system_prompt.clone())
                .messages(self.history.iter().chain(turn_messages.iter()).cloned())
                .tools(self.tool_definitions())
                .build();

            let response = self.model.completion(request).await?;
            usage_total += response.usage;

            let mut text_parts = Vec::new();
            let mut tool_calls: Vec<ToolCall> = Vec::new();
            for content in response.choice.iter() {
                match content {
                    AssistantContent::Text(t) => text_parts.push(t.clone()),
                    AssistantContent::ToolCall(call) => tool_calls.push(call.clone()),
                    AssistantContent::Reasoning(_) | AssistantContent::Image(_) => {}
                }
            }

            if tool_calls.is_empty() {
                let text = text_parts
                    .iter()
                    .map(|t| t.text())
                    .collect::<Vec<_>>()
                    .join("\n");
                turn_messages.push(Message::assistant(text.clone()));
                self.commit_turn(user_input, turn_messages);
                return Ok(TurnSummary {
                    text,
                    tool_calls: tool_calls_total,
                    usage: usage_total,
                    final_history: self.history.clone(),
                });
            }

            let mut contents: Vec<AssistantContent> =
                text_parts.into_iter().map(AssistantContent::Text).collect();
            contents.extend(tool_calls.iter().cloned().map(AssistantContent::ToolCall));
            turn_messages.push(Message::Assistant {
                id: response.message_id,
                content: rig::OneOrMany::from_iter_optional(contents)
                    .expect("assistant message has at least one tool call"),
            });

            for call in &tool_calls {
                let output = self.execute_tool(call).await?;
                tool_calls_total += 1;
                turn_messages.push(Message::tool_result_with_call_id(
                    call.id.clone(),
                    call.call_id.clone(),
                    output,
                ));
            }
        }

        self.commit_turn(user_input, turn_messages);
        Err(AgentError::MaxTurns {
            turns: self.max_turns,
        })
    }

    /// Run one user turn with streaming output.
    ///
    /// Returns a channel receiver. The caller reads events as they arrive.
    /// The agent loop runs on a spawned task. After the stream completes,
    /// the caller should extract `final_history` from the `TurnComplete`
    /// event and call `set_history` to persist the new state.
    pub async fn run_streaming(
        &self,
        user_input: &str,
    ) -> Result<mpsc::Receiver<StreamEvent>, AgentError>
    where
        M: 'static,
        M::StreamingResponse: Send,
    {
        let (tx, rx) = mpsc::channel(32);
        let model = self.model.clone();
        let tools = self.tools_arc();
        let max_turns = self.max_turns;
        let mut history = self.history.clone();
        let user_input = user_input.to_string();

        tokio::spawn(async move {
            let result = run_streaming_loop(
                model,
                tools,
                &mut history,
                user_input.to_string(),
                max_turns,
                &tx,
            )
            .await;
            // Update the agent's history on completion.
            // (History is sent back to the agent via a final message or
            //  we update it after the stream. For now, the caller handles it.)
            let _ = result;
        });

        Ok(rx)
    }

    /// Dispatch a single tool call by name and render its output as text.
    pub(crate) async fn execute_tool(&self, call: &ToolCall) -> Result<String, AgentError> {
        let name = &call.function.name;
        let tool = self
            .tools
            .iter()
            .find(|t| t.name() == name)
            .ok_or_else(|| AgentError::Tool {
                name: name.clone(),
                message: "unknown tool".into(),
            })?;
        let output = tool
            .execute(call.function.arguments.clone())
            .await
            .map_err(|e| AgentError::Tool {
                name: name.clone(),
                message: e.to_string(),
            })?;
        Ok(output.render())
    }

    /// Append the completed turn to the persistent history.
    pub(crate) fn commit_turn(&mut self, user_input: &str, turn_messages: Vec<Message>) {
        self.history.push(Message::user(user_input));
        self.history.extend(turn_messages);
    }
}

/// The inner streaming loop, run on a spawned task.
///
/// Consumes the model stream, executes tools when complete tool calls
/// arrive, and sends [`StreamEvent`]s to the caller.
async fn run_streaming_loop<M: CompletionModel>(
    model: M,
    tools: Arc<Vec<PortableDynamicTool>>,
    history: &mut Vec<Message>,
    user_input: String,
    max_turns: usize,
    tx: &mpsc::Sender<StreamEvent>,
) -> Result<TurnSummary, AgentError>
where
    M::StreamingResponse: Send,
{
    let mut turn_messages: Vec<Message> = Vec::new();
    let mut tool_calls_total: usize = 0;
    let mut usage_total = Usage::new();

    for _turn in 0..max_turns {
        // Build the request.
        let request = model
            .completion_request(Message::user(user_input.clone()))
            .messages(history.iter().chain(turn_messages.iter()).cloned())
            .tools(tools.iter().map(|t| t.definition()).collect::<Vec<_>>())
            .build();

        let mut stream = model
            .stream(request)
            .await
            .map_err(|e| AgentError::Rig(e.to_string()))?;

        // Track tool calls and their results during this model call.
        let mut pending_tool_calls: Vec<ToolCall> = Vec::new();
        let mut pending_results: Vec<(ToolCall, String)> = Vec::new();
        let mut text_buf = String::new();

        while let Some(item) = stream.next().await {
            match item {
                Ok(rig::streaming::StreamedAssistantContent::Text(t)) => {
                    let delta = t.text().to_string();
                    text_buf.push_str(&delta);
                    let _ = tx.send(StreamEvent::TextDelta { text: delta }).await;
                }
                Ok(rig::streaming::StreamedAssistantContent::ToolCallDelta {
                    id, content, ..
                }) => {
                    use rig::streaming::ToolCallDeltaContent;
                    match content {
                        ToolCallDeltaContent::Name(name) => {
                            let _ = tx
                                .send(StreamEvent::ToolCallStart {
                                    id: id.clone(),
                                    name: name.clone(),
                                })
                                .await;
                        }
                        ToolCallDeltaContent::Delta(args) => {
                            let _ = tx
                                .send(StreamEvent::ToolCallArgs {
                                    id: id.clone(),
                                    args_delta: args,
                                })
                                .await;
                        }
                    }
                }
                Ok(rig::streaming::StreamedAssistantContent::ToolCall { tool_call, .. }) => {
                    let _ = tx
                        .send(StreamEvent::ToolCallReady {
                            id: tool_call.id.clone(),
                            name: tool_call.function.name.clone(),
                            arguments: tool_call.function.arguments.clone(),
                        })
                        .await;

                    // Execute the tool.
                    let name = tool_call.function.name.clone();
                    let tool = tools.iter().find(|t| t.name() == name);
                    match tool {
                        Some(t) => match t.execute(tool_call.function.arguments.clone()).await {
                            Ok(output) => {
                                let rendered = output.render();
                                let preview = if rendered.len() > 200 {
                                    format!("{}…", &rendered[..200])
                                } else {
                                    rendered.clone()
                                };
                                let _ = tx
                                    .send(StreamEvent::ToolResult {
                                        id: tool_call.id.clone(),
                                        name: name.clone(),
                                        result_preview: preview,
                                        result: rendered.clone(),
                                    })
                                    .await;
                                tool_calls_total += 1;
                                pending_results.push((tool_call.clone(), rendered));
                            }
                            Err(e) => {
                                let _ = tx
                                    .send(StreamEvent::Error {
                                        message: e.to_string(),
                                    })
                                    .await;
                                return Err(AgentError::Tool {
                                    name: name.clone(),
                                    message: e.to_string(),
                                });
                            }
                        },
                        None => {
                            let msg = format!("unknown tool: {name}");
                            let _ = tx
                                .send(StreamEvent::Error {
                                    message: msg.clone(),
                                })
                                .await;
                            return Err(AgentError::Tool {
                                name: name.clone(),
                                message: msg,
                            });
                        }
                    }
                    pending_tool_calls.push(tool_call);
                }
                Ok(rig::streaming::StreamedAssistantContent::Final(r)) => {
                    usage_total += r.token_usage();
                }
                Ok(rig::streaming::StreamedAssistantContent::ReasoningDelta { .. })
                | Ok(rig::streaming::StreamedAssistantContent::Reasoning(_)) => {
                    // Silently absorb reasoning — not shown to the user yet.
                }
                Ok(rig::streaming::StreamedAssistantContent::Unknown(_)) => {}
                Err(e) => {
                    let _ = tx
                        .send(StreamEvent::Error {
                            message: e.to_string(),
                        })
                        .await;
                    return Err(AgentError::Rig(e.to_string()));
                }
            }
        }
        // Capture message_id from the stream.
        let message_id = stream.message_id.clone();

        // If no tool calls were made, the turn is complete.
        if pending_tool_calls.is_empty() {
            turn_messages.push(Message::assistant(text_buf.clone()));
            history.push(Message::user(user_input));
            history.extend(turn_messages);
            let summary = TurnSummary {
                text: text_buf,
                tool_calls: tool_calls_total,
                usage: usage_total,
                final_history: history.clone(),
            };
            let _ = tx
                .send(StreamEvent::TurnComplete {
                    summary: summary.clone(),
                })
                .await;
            return Ok(summary);
        }

        // Tool calls were executed. Build the assistant message and loop.
        let mut contents: Vec<AssistantContent> = Vec::new();
        if !text_buf.is_empty() {
            contents.push(AssistantContent::Text(rig::completion::message::Text::new(
                text_buf,
            )));
        }
        contents.extend(
            pending_tool_calls
                .iter()
                .cloned()
                .map(AssistantContent::ToolCall),
        );
        turn_messages.push(Message::Assistant {
            id: message_id,
            content: rig::OneOrMany::from_iter_optional(contents)
                .expect("assistant message has content"),
        });

        // Push tool results AFTER the assistant message.
        for (call, rendered) in pending_results {
            turn_messages.push(Message::tool_result_with_call_id(
                call.id,
                call.call_id,
                rendered,
            ));
        }
    }

    // Max turns exceeded.
    history.push(Message::user(user_input));
    history.extend(turn_messages);
    let _ = tx
        .send(StreamEvent::Error {
            message: format!("exceeded maximum of {max_turns} model turns"),
        })
        .await;
    Err(AgentError::MaxTurns { turns: max_turns })
}

#[cfg(test)]
mod tests {
    use super::*;
    use rig::test_utils::{MockCompletionModel, MockTurn};

    fn echo_agent() -> Agent<MockCompletionModel> {
        let mut agent = Agent::new(MockCompletionModel::text("unused"), "test system");
        agent.add_tool(crate::tool::builtin_echo());
        agent
    }

    #[tokio::test]
    async fn test_simple_text_reply() {
        let mut agent = echo_agent();
        let summary = agent.run("hi").await.expect("run succeeds");
        assert_eq!(summary.text, "unused");
        assert_eq!(summary.tool_calls, 0);
        assert_eq!(agent.history().len(), 2);
    }

    #[tokio::test]
    async fn test_tool_call_round_trip() {
        let model = MockCompletionModel::from_turns([
            MockTurn::tool_call("call_1", "echo", serde_json::json!({"text": "ping"})),
            MockTurn::text("echoed: ping"),
        ]);
        let mut agent = Agent::new(model, "test system");
        agent.add_tool(crate::tool::builtin_echo());

        let summary = agent.run("echo ping").await.expect("run succeeds");
        assert_eq!(summary.text, "echoed: ping");
        assert_eq!(summary.tool_calls, 1);

        let history = agent.history();
        assert_eq!(history.len(), 4);
    }

    #[tokio::test]
    async fn test_max_turns_exceeded() {
        let model = MockCompletionModel::from_turns(std::iter::repeat_n(
            MockTurn::tool_call("call_x", "echo", serde_json::json!({"text": "x"})),
            50,
        ));
        let mut agent = Agent::new(model, "test system");
        agent.add_tool(crate::tool::builtin_echo());
        agent.set_max_turns(3);

        let err = agent.run("loop").await.expect_err("run must fail");
        assert!(matches!(err, AgentError::MaxTurns { turns: 3 }));
    }

    #[tokio::test]
    async fn test_unknown_tool_fails() {
        let model = MockCompletionModel::from_turns([MockTurn::tool_call(
            "call_1",
            "nonexistent",
            serde_json::json!({}),
        )]);
        let mut agent = Agent::new(model, "test system");
        let err = agent.run("do it").await.expect_err("run must fail");
        assert!(matches!(err, AgentError::Tool { .. }));
    }
}

//! Built-in tools for the agent.
//!
//! Tools are rig [`PortableDynamicTool`]s: name + description + JSON schema +
//! an async callback taking raw `serde_json::Value` arguments.

use std::path::{Path, PathBuf};
use std::process::Stdio;
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{Duration, Instant};

use chrono::Utc;
use grep_regex::{RegexMatcher, RegexMatcherBuilder};
use grep_searcher::{Searcher, Sink, SinkMatch};
use rig::tool::{PortableDynamicTool, ToolExecutionError, ToolOutput};
use serde_json::json;
use tokio::io::AsyncReadExt as _;

use crate::source::{SourceError, SourceTree};

/// Map a [`SourceError`] onto a rig tool error with the right kind.
pub(crate) fn map_source_err(e: SourceError) -> ToolExecutionError {
    match e {
	SourceError::NotFound(p) => {
	    ToolExecutionError::not_found(format!("no such path: {}", p.display()))
	}
	SourceError::Ignored(p) => {
	    ToolExecutionError::permission_denied(format!("path is git-ignored: {}", p.display()))
	}
	SourceError::Escape(p) => ToolExecutionError::permission_denied(format!(
	    "path escapes the repository: {}",
	    p.display()
	)),
	other => ToolExecutionError::provider(other.to_string()),
    }
}

/// Tool: report the current local date and time.
pub fn builtin_get_time() -> PortableDynamicTool {
    PortableDynamicTool::new(
	"get_time",
	"Get the current local date and time in RFC 3339 format.",
	json!({
	    "type": "object",
	    "properties": {}
	}),
	|_args: serde_json::Value| {
	    Box::pin(async move {
		let now = chrono::Local::now().to_rfc3339();
		Ok(ToolOutput::text(now))
	    })
	},
    )
}

/// Tool: echo the provided text back verbatim.
pub fn builtin_echo() -> PortableDynamicTool {
    PortableDynamicTool::new(
	"echo",
	"Echo the provided text back verbatim.",
	json!({
	    "type": "object",
	    "properties": {
	    "text": { "type": "string", "description": "Text to echo" }
	    },
	    "required": ["text"]
	}),
	|args: serde_json::Value| {
	    Box::pin(async move {
		let text = args
		    .get("text")
		    .and_then(|v| v.as_str())
		    .unwrap_or_default()
		    .to_string();
		Ok(ToolOutput::text(text))
	    })
	},
    )
}

/// Tool: read a text file from the git repository.
pub fn builtin_read_file(tree: Arc<SourceTree>) -> PortableDynamicTool {
    PortableDynamicTool::new(
	"read_file",
	"Read a text file from the git repository. `path` is relative to the repo root. \
	 Git-ignored paths cannot be read. Returns up to 64 KiB.",
	json!({
	    "type": "object",
	    "properties": {
	    "path": { "type": "string", "description": "Path relative to the repo root" }
	    },
	    "required": ["path"]
	}),
	move |args: serde_json::Value| {
	    let tree = tree.clone();
	    Box::pin(async move {
		let rel = args.get("path").and_then(|v| v.as_str()).ok_or_else(|| {
		    ToolExecutionError::invalid_args("missing string field 'path'")
		})?;
		tree.read(Path::new(rel))
		    .map(ToolOutput::text)
		    .map_err(map_source_err)
	    })
	},
    )
}

/// Tool: list files and directories in the git repository.
pub fn builtin_list_dir(tree: Arc<SourceTree>) -> PortableDynamicTool {
    PortableDynamicTool::new(
	"list_dir",
	"List files and directories in the git repository. `path` is relative to the repo root \
	 (default: the root itself). `depth` controls recursion (default 1, max 4). \
	 Git-ignored paths are never listed. One line per entry: type + path.",
	json!({
	    "type": "object",
	    "properties": {
	    "path": { "type": "string", "description": "Directory relative to repo root" },
	    "depth": { "type": "integer", "description": "Recursion depth (1-4)" }
	    }
	}),
	move |args: serde_json::Value| {
	    let tree = tree.clone();
	    Box::pin(async move {
		let rel = args.get("path").and_then(|v| v.as_str()).unwrap_or(".");
		let depth = args
		    .get("depth")
		    .and_then(|v| v.as_u64())
		    .unwrap_or(1)
		    .clamp(1, 4) as usize;
		let walk = tree.walk(Path::new(rel), depth).map_err(map_source_err)?;
		let mut lines = Vec::new();
		for entry in walk {
		    let entry = entry.map_err(|e| ToolExecutionError::provider(e.to_string()))?;
		    if entry.depth() == 0 {
			continue;
		    }
		    let ty = match entry.file_type() {
			Some(t) if t.is_dir() => "dir ",
			Some(t) if t.is_file() => "file",
			Some(t) if t.is_symlink() => "link",
			_ => "oth ",
		    };
		    let p = entry
			.path()
			.strip_prefix(tree.root())
			.unwrap_or(entry.path());
		    lines.push(format!("{ty} {}", p.display()));
		}
		Ok(ToolOutput::text(lines.join("\n")))
	    })
	},
    )
}

// ── run_command ──────────────────────────────────────────────────

/// Default timeout for `run_command`.
const DEFAULT_TIMEOUT_SECS: u64 = 120;
/// Maximum allowed timeout for `run_command`.
const MAX_TIMEOUT_SECS: u64 = 600;

/// Per-process sequence number for trace filenames. The tool cannot see the
/// session turn number, so unix-ms + a per-process counter disambiguates
/// traces within a session directory.
static TRACE_SEQ: AtomicU64 = AtomicU64::new(0);

/// Result of executing a command (spawn, wait, capture, timeout).
struct CommandOutcome {
    exit_code: Option<i32>,
    timed_out: bool,
    duration_ms: u64,
    stdout: String,
    stderr: String,
}

/// Validate a whitespace-split command against the allowlist.
///
/// `argv[0]` must be `cargo` or `git`. Cargo subcommands are limited to
/// `check`, `build`, `test`, `clippy`, `fmt`, `doc`, and `run -p hanihi-eval`.
/// Git is limited to the read-only verbs `status`, `diff`, `log`, `show`, and
/// `apply --check`. Flags that would change the working directory
/// (`--manifest-path`, `-C`/`--directory`) are rejected outright — the cwd is
/// pinned to the repo root and nothing may escape it.
fn check_command_argv(argv: &[String]) -> Result<(), String> {
    let Some(program) = argv.first() else {
	return Err("empty command".into());
    };
    match program.as_str() {
	"cargo" => {
	    let Some(sub) = argv.get(1) else {
		return Err(
		    "cargo requires a subcommand (check, build, test, clippy, fmt, doc, run)"
			.into(),
		);
	    };
	    if argv.iter().any(|a| a == "--manifest-path") {
		return Err(
		    "cargo --manifest-path is not allowed (cwd is pinned to the repo root)".into(),
		);
	    }
	    match sub.as_str() {
		"check" | "build" | "test" | "clippy" | "fmt" | "doc" => Ok(()),
		"run" => {
		    // Only `cargo run -p hanihi-eval` is permitted.
		    let mut package: Option<&str> = None;
		    let mut iter = argv[1..].iter().peekable();
		    while let Some(a) = iter.next() {
			if a == "--" {
			    break;
			}
			if a == "-p" || a == "--package" {
			    package = iter.peek().map(|s| s.as_str());
			}
		    }
		    match package {
			Some("hanihi-eval") => Ok(()),
			Some(other) => Err(format!(
			    "cargo run is restricted to -p hanihi-eval (got -p {other})"
			)),
			None => Err("cargo run requires -p hanihi-eval".into()),
		    }
		}
		other => Err(format!("cargo subcommand '{other}' is not allowed")),
	    }
	}
	"git" => {
	    let Some(sub) = argv.get(1) else {
		return Err("git requires a subcommand (status, diff, log, show, apply)".into());
	    };
	    if argv.iter().any(|a| a == "-C" || a == "--directory") {
		return Err(
		    "git -C/--directory is not allowed (cwd is pinned to the repo root)".into(),
		);
	    }
	    match sub.as_str() {
		"status" | "diff" | "ls-files" | "log" | "show" => Ok(()),
		"apply" => {
		    if !argv.iter().any(|a| a == "--check") {
			return Err("git apply is restricted to --check".into());
		    }
		    Ok(())
		}
		other => Err(format!("git subcommand '{other}' is not allowed")),
	    }
	}
	other => Err(format!(
	    "command '{other}' is not allowed (only cargo and git)"
	)),
    }
}

/// Build the minimal environment passed to child processes: PATH, HOME, and
/// CARGO_* / RUSTUP_* (needed for cargo/rustup to resolve the toolchain).
/// Everything else (API keys, etc.) is dropped.
pub(crate) fn scrubbed_env() -> Vec<(String, String)> {
    std::env::vars()
	.filter(|(k, _)| {
	    k == "PATH" || k == "HOME" || k.starts_with("CARGO_") || k.starts_with("RUSTUP_")
	})
	.collect()
}

/// Read a pipe to EOF as a lossy UTF-8 string.
async fn read_all<R>(mut reader: R) -> std::io::Result<String>
where
    R: tokio::io::AsyncRead + Unpin,
{
    let mut buf = Vec::new();
    reader.read_to_end(&mut buf).await?;
    Ok(String::from_utf8_lossy(&buf).into_owned())
}

/// Cap a string at `MAX_READ_BYTES`, appending a truncation note.
fn cap_output(s: &str) -> String {
    if s.len() <= crate::source::MAX_READ_BYTES {
	s.to_string()
    } else {
	let cut = s.floor_char_boundary(crate::source::MAX_READ_BYTES);
	let mut out = String::with_capacity(cut + 64);
	out.push_str(&s[..cut]);
	out.push_str(&format!("\n…[truncated, {} bytes total]", s.len()));
	out
    }
}

/// Spawn `argv`, capture stdout/stderr, enforce a timeout (killing the child
/// on expiry), and return the outcome. The allowlist check happens in the
/// tool wrapper; this runs whatever argv it is given (used directly by tests).
async fn execute_captured(
    argv: &[String],
    cwd: &Path,
    timeout: Duration,
) -> Result<CommandOutcome, String> {
    let mut cmd = tokio::process::Command::new(&argv[0]);
    cmd.args(&argv[1..]);
    cmd.current_dir(cwd);
    cmd.stdin(Stdio::null());
    cmd.stdout(Stdio::piped());
    cmd.stderr(Stdio::piped());
    cmd.env_clear();
    for (k, v) in scrubbed_env() {
	cmd.env(k, v);
    }

    let mut child = cmd
	.spawn()
	.map_err(|e| format!("failed to spawn '{}': {e}", argv[0]))?;
    let stdout_pipe = child.stdout.take().expect("piped stdout");
    let stderr_pipe = child.stderr.take().expect("piped stderr");

    // Read both pipes concurrently with the wait so a large stream on one
    // pipe cannot deadlock the other.
    let stdout_task = tokio::spawn(read_all(stdout_pipe));
    let stderr_task = tokio::spawn(read_all(stderr_pipe));

    let started = Instant::now();
    let status_result = tokio::time::timeout(timeout, child.wait()).await;

    let (exit_code, timed_out) = match status_result {
	Ok(Ok(status)) => (status.code(), false),
	Ok(Err(e)) => return Err(format!("waiting for '{}': {e}", argv[0])),
	Err(_elapsed) => {
	    // Kill the child on expiry; the readers hit EOF and complete.
	    let _ = child.kill().await;
	    let _ = child.wait().await;
	    (None, true)
	}
    };

    let stdout = stdout_task
	.await
	.map_err(|e| format!("stdout task failed: {e}"))?
	.map_err(|e| format!("reading stdout: {e}"))?;
    let stderr = stderr_task
	.await
	.map_err(|e| format!("stderr task failed: {e}"))?
	.map_err(|e| format!("reading stderr: {e}"))?;

    Ok(CommandOutcome {
	exit_code,
	timed_out,
	duration_ms: started.elapsed().as_millis() as u64,
	stdout,
	stderr,
    })
}

/// Persist a command execution to `<traces-dir>/<unix-ms>-<seq>.cmd.json`.
fn write_trace(
    traces_dir: &Path,
    command: &str,
    outcome: &CommandOutcome,
) -> std::io::Result<PathBuf> {
    std::fs::create_dir_all(traces_dir)?;
    let seq = TRACE_SEQ.fetch_add(1, Ordering::Relaxed);
    let ms = Utc::now().timestamp_millis();
    let name = format!("{ms}-{seq}.cmd.json");
    let path = traces_dir.join(name);
    let obj = json!({
    "ts": Utc::now().to_rfc3339(),
    "command": command,
    "exit_code": outcome.exit_code,
    "duration_ms": outcome.duration_ms,
    "stdout": outcome.stdout,
    "stderr": outcome.stderr,
    });
    std::fs::write(&path, serde_json::to_string_pretty(&obj)?)?;
    Ok(path)
}

/// Render the tool result: exit code + duration + truncated output + trace path.
fn render_command_result(command: &str, outcome: &CommandOutcome, trace_path: &Path) -> String {
    let code = match outcome.exit_code {
	Some(c) => c.to_string(),
	None if outcome.timed_out => "killed (timeout)".to_string(),
	None => "killed (signal)".to_string(),
    };
    let mut out = format!(
	"command: {command}\nexit code: {code}\nduration: {}ms\n",
	outcome.duration_ms
    );
    if !outcome.stdout.is_empty() {
	out.push_str("--- stdout ---\n");
	out.push_str(&cap_output(&outcome.stdout));
	out.push('\n');
    }
    if !outcome.stderr.is_empty() {
	out.push_str("--- stderr ---\n");
	out.push_str(&cap_output(&outcome.stderr));
	out.push('\n');
    }
    out.push_str(&format!("trace: {}", trace_path.display()));
    out
}

/// Tool: run an allowlisted `cargo`/`git` command inside the repo root.
///
/// Registered always (it is an analysis/build tool, not a write tool). The
/// command is split on whitespace (no shell), validated against an allowlist,
/// executed with a scrubbed environment and a timeout, and the full output is
/// persisted to a trace file. The result carries exit code + duration +
/// truncated stdout/stderr + the trace path.
pub fn builtin_run_command(tree: Arc<SourceTree>, traces_dir: PathBuf) -> PortableDynamicTool {
    PortableDynamicTool::new(
	"run_command",
	"Run an allowlisted command inside the repository root. No shell: the command is \
	 split on whitespace into argv. cargo subcommands: check, build, test, clippy, fmt, \
	 doc, run -p hanihi-eval. git subcommands: status, diff, log, show, apply --check. \
	 cwd is pinned to the repo root; the environment is scrubbed (PATH, HOME, CARGO_* \
	 only); output is capped at 64 KiB; the full output is written to a trace file. \
	 Returns exit code, duration, stdout/stderr (truncated), and the trace path.",
	json!({
	    "type": "object",
	    "properties": {
	    "command": {
		"type": "string",
		"description": "Allowlisted command, e.g. \"cargo check --workspace\""
	    },
	    "timeout_secs": {
		"type": "integer",
		"description": "Max seconds (default 120, max 600)"
	    }
	    },
	    "required": ["command"]
	}),
	move |args: serde_json::Value| {
	    let tree = tree.clone();
	    let traces_dir = traces_dir.clone();
	    Box::pin(async move {
		let command = args
		    .get("command")
		    .and_then(|v| v.as_str())
		    .ok_or_else(|| {
			ToolExecutionError::invalid_args("missing string field 'command'")
		    })?
		    .to_string();
		let timeout_secs = args
		    .get("timeout_secs")
		    .and_then(|v| v.as_u64())
		    .unwrap_or(DEFAULT_TIMEOUT_SECS)
		    .clamp(1, MAX_TIMEOUT_SECS);

		let argv: Vec<String> = command.split_whitespace().map(String::from).collect();
		if argv.is_empty() {
		    return Err(ToolExecutionError::invalid_args("empty command"));
		}
		check_command_argv(&argv).map_err(ToolExecutionError::permission_denied)?;

		let outcome =
		    execute_captured(&argv, tree.root(), Duration::from_secs(timeout_secs))
			.await
			.map_err(ToolExecutionError::provider)?;
		let trace_path = write_trace(&traces_dir, &command, &outcome)
		    .map_err(|e| ToolExecutionError::provider(format!("writing trace: {e}")))?;
		Ok(ToolOutput::text(render_command_result(
		    &command,
		    &outcome,
		    &trace_path,
		)))
	    })
	},
    )
}

/// Maximum number of matches `grep` returns before truncating.
const MAX_GREP_MATCHES: usize = 200;
/// Maximum total bytes of `grep` output before truncating.
const MAX_GREP_BYTES: usize = 64 * 1024;

/// Collects `path:line: text` matches for [`builtin_grep`], capped at
/// [`MAX_GREP_MATCHES`] matches / [`MAX_GREP_BYTES`] bytes.
///
/// `grep-searcher`'s `SinkMatch` carries no path, so the caller sets
/// [`MatchSink::current_path`] before each single-file search.
struct MatchSink {
    current_path: PathBuf,
    lines: Vec<String>,
    bytes: usize,
    capped: bool,
}

impl Sink for MatchSink {
    type Error = Box<dyn std::error::Error>;

    fn matched(
	&mut self,
	_searcher: &Searcher,
	lines: &SinkMatch<'_>,
    ) -> Result<bool, Self::Error> {
	let path = self.current_path.display();
	let line_no = lines.line_number().unwrap_or(0);
	let text = String::from_utf8_lossy(lines.bytes());
	let entry = format!("{path}:{line_no}: {}", text.trim_end());
	self.bytes += entry.len();
	self.lines.push(entry);
	if self.lines.len() >= MAX_GREP_MATCHES || self.bytes >= MAX_GREP_BYTES {
	    self.capped = true;
	    return Ok(false);
	}
	Ok(true)
    }
}

/// Tool: regex-search file contents inside the git repository.
///
/// Walks the repo honouring ignore rules (via [`SourceTree::walk`]) and
/// searches each file with ripgrep's searcher. Results are
/// `path:line: text` entries capped at [`MAX_GREP_MATCHES`] matches /
/// [`MAX_GREP_BYTES`] bytes. Binary files are skipped.
pub fn builtin_grep(tree: Arc<SourceTree>) -> PortableDynamicTool {
    PortableDynamicTool::new(
	"grep",
	"Search file contents in the git repository with a regular expression. `pattern` is a \
	 regex (ripgrep syntax). `path` is a directory relative to the repo root (default: the \
	 root). `ignore_case` makes the match case-insensitive. Git-ignored paths are never \
	 searched. Results are `path:line: text` entries, capped at 200 matches.",
	json!({
	    "type": "object",
	    "properties": {
	    "pattern": { "type": "string", "description": "Regular expression to search for" },
	    "path": { "type": "string", "description": "Directory relative to repo root (default: root)" },
	    "ignore_case": { "type": "boolean", "description": "Case-insensitive match" }
	    },
	    "required": ["pattern"]
	}),
	move |args: serde_json::Value| {
	    let tree = tree.clone();
	    Box::pin(async move {
		let pattern = args
		    .get("pattern")
		    .and_then(|v| v.as_str())
		    .ok_or_else(|| {
			ToolExecutionError::invalid_args("missing string field 'pattern'")
		    })?;
		let rel = args.get("path").and_then(|v| v.as_str()).unwrap_or(".");
		let ignore_case = args
		    .get("ignore_case")
		    .and_then(|v| v.as_bool())
		    .unwrap_or(false);

		let matcher = if ignore_case {
		    RegexMatcherBuilder::new()
			.case_insensitive(true)
			.build(pattern)
		} else {
		    RegexMatcher::new(pattern)
		}
		.map_err(|e| ToolExecutionError::invalid_args(format!("invalid regex: {e}")))?;

		let mut sink = MatchSink {
		    current_path: PathBuf::new(),
		    lines: Vec::new(),
		    bytes: 0,
		    capped: false,
		};
		let mut searcher = Searcher::new();
		searcher.set_binary_detection(grep_searcher::BinaryDetection::quit(b'\x00'));

		let walk = tree
		    .walk(Path::new(rel), usize::MAX)
		    .map_err(map_source_err)?;
		for entry in walk {
		    let entry = entry.map_err(|e| ToolExecutionError::provider(e.to_string()))?;
		    if !entry.file_type().map(|t| t.is_file()).unwrap_or(false) {
			continue;
		    }
		    let path = entry.path();
		    sink.current_path = path.to_path_buf();
		    searcher
			.search_path(matcher.clone(), path, &mut sink)
			.map_err(|e| {
			    ToolExecutionError::provider(format!(
				"searching {}: {e}",
				path.display()
			    ))
			})?;
		    if sink.capped {
			break;
		    }
		}

		let mut out = if sink.lines.is_empty() {
		    "no matches".to_string()
		} else {
		    sink.lines.join("\n")
		};
		if sink.capped {
		    out.push_str("\n…[truncated: too many matches]");
		}
		Ok(ToolOutput::text(out))
	    })
	},
    )
}

/// Tool: read entries from this session's event log (the agent's own trace).
///
/// The log lives outside the repo (under the working dir), so the source-tree
/// tools cannot see it. This tool gives the agent a window into its own past
/// executions — the raw material for studying traces of execution.
pub fn builtin_read_session_log(log_path: PathBuf) -> PortableDynamicTool {
    PortableDynamicTool::new(
	"read_session_log",
	"Read entries from this session's event log. `kind` filters by event kind \
	 (user_input, llm_prompt, llm_response, tool_execution, turn_complete, error, \
	 session_created, ...). `turn` filters by turn number. `tail` returns only the last N \
	 entries (default 50, max 1000). Entries are rendered as compact JSON, one per line.",
	json!({
	    "type": "object",
	    "properties": {
	    "kind": { "type": "string", "description": "Event kind filter" },
	    "turn": { "type": "integer", "description": "Turn number filter" },
	    "tail": { "type": "integer", "description": "Last N entries (default 50, max 1000)" }
	    }
	}),
	move |args: serde_json::Value| {
	    let log_path = log_path.clone();
	    Box::pin(async move {
		let kind = args.get("kind").and_then(|v| v.as_str()).map(String::from);
		let turn = args.get("turn").and_then(|v| v.as_u64());
		let tail = args
		    .get("tail")
		    .and_then(|v| v.as_u64())
		    .unwrap_or(50)
		    .clamp(1, 1000) as usize;

		let content = std::fs::read_to_string(&log_path).map_err(|e| {
		    ToolExecutionError::provider(format!("reading {}: {e}", log_path.display()))
		})?;
		let mut entries: Vec<serde_json::Value> = Vec::new();
		for line in content.lines() {
		    let line = line.trim();
		    if line.is_empty() {
			continue;
		    }
		    let Ok(v) = serde_json::from_str::<serde_json::Value>(line) else {
			continue;
		    };
		    if let Some(k) = &kind
			&& v.get("kind").and_then(|x| x.as_str()) != Some(k.as_str())
		    {
			continue;
		    }
		    if let Some(t) = turn
			&& v.get("turn").and_then(|x| x.as_u64()) != Some(t)
		    {
			continue;
		    }
		    entries.push(v);
		}
		let start = entries.len().saturating_sub(tail);
		let mut rendered = entries[start..]
		    .iter()
		    .map(|v| v.to_string())
		    .collect::<Vec<_>>()
		    .join("\n");
		if rendered.is_empty() {
		    rendered = "no log entries match".to_string();
		}
		Ok(ToolOutput::text(cap_output(&rendered)))
	    })
	},
    )
}

